package com.bank.jvm.humongous;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class StatementBatchSimulator {
    private static final Logger log = Logger.getLogger(StatementBatchSimulator.class.getName());

    public static void main(String[] args) {
        RegionMath math = new RegionMath();
        log.info(() -> "Region size=" + math.regionSizeMb() + "MB, humongous threshold="
                + math.humongousThresholdMb() + "MB");

        StatementRenderer renderer = new StatementRenderer(math);

        // BAD path: one giant array per statement — humongous allocations.
        log.warning("Rendering with ONE giant buffer per statement (humongous)");
        renderer.renderBig("SAV2001", 9); // 9MB buffer

        // GOOD path: chunked rendering — every chunk stays under the threshold.
        log.info("Rendering with CHUNKED buffers (never humongous)");
        renderer.renderChunked("SAV2001", 9, 2); // 9MB in 2MB chunks

        log.info("Chunked path keeps every object in normal Eden regions");
    }
}

// ─── Would be in StatementRenderer.java in a real project ───
class StatementRenderer {
    private static final Logger log = Logger.getLogger(StatementRenderer.class.getName());
    private final RegionMath math;

    StatementRenderer(RegionMath math) { this.math = math; }

    // Allocates one large array; likely humongous.
    void renderBig(String accountId, int sizeMb) {
        int bytes = sizeMb * 1024 * 1024;
        byte[] buffer = new byte[bytes];
        boolean humongous = math.isHumongous(bytes);
        int regions = math.regionsConsumed(bytes);
        log.warning(() -> "Statement " + accountId + " buffer=" + sizeMb + "MB humongous="
                + humongous + " consumes " + regions + " whole region(s)");
        buffer[0] = 1; // touch so it is not optimised away
    }

    // Allocates the same data in small chunks; each stays under the threshold.
    void renderChunked(String accountId, int totalMb, int chunkMb) {
        List<byte[]> chunks = new ArrayList<>();
        int remaining = totalMb;
        while (remaining > 0) {
            int thisChunk = Math.min(chunkMb, remaining);
            int bytes = thisChunk * 1024 * 1024;
            byte[] chunk = new byte[bytes];
            chunk[0] = 1;
            chunks.add(chunk);
            boolean humongous = math.isHumongous(bytes);
            log.info("Chunk " + thisChunk + "MB humongous=" + humongous);
            remaining -= thisChunk;
        }
        log.info(() -> "Statement " + accountId + " rendered in " + chunks.size() + " safe chunks");
    }
}
