package com.bank.jvm.humongous;

class RegionMath {
    // Assume 8MB regions for the demo; in production read -XX:G1HeapRegionSize.
    private static final int REGION_BYTES = 8 * 1024 * 1024;

    int regionSizeMb() { return REGION_BYTES / (1024 * 1024); }
    int humongousThresholdMb() { return regionSizeMb() / 2; }

    boolean isHumongous(int objectBytes) {
        return objectBytes > REGION_BYTES / 2;
    }

    int regionsConsumed(int objectBytes) {
        return (objectBytes + REGION_BYTES - 1) / REGION_BYTES; // round up
    }
}
